breakdown-drop-arrangement-over-bars.code:
const drums = s("bd*4,hh*8").bank("RolandTR909")
const pad = note("c3 eb3 g3 bb3").s("triangle").slow(2).room(0.4)
setcpm(128/4)
arrange([8, pad], [8, drums], [8, stack(drums, pad)])

build-drop.code:
setcpm(124/4)
const kick = note("g1*4").s("sine").hpf(30).penv(24).pdecay(0.08).decay(0.25).sustain(0)
const pad = note("<[c3,eb3,g3] [bb2,d3,f3]>").s("triangle").slow(2).room(0.4)
const top = s("~ white ~ white").hpf(7000).decay(0.05).sustain(0).gain(0.4)
arrange([4, pad], [4, stack(kick, pad)], [4, stack(kick, pad, top)])
